import {
  Group,
  Mesh,
  BoxGeometry,
  SphereGeometry,
  ConeGeometry,
  Vector3,
} from "three";

// Deterministic PRNG (mulberry32) so a given seed always yields the same shard.
function makeRng(seed) {
  let a = seed >>> 0;
  return function rng() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function buildShard(rng) {
  const shard = new Group();
  shard.name = "shard";

  const geometries = [
    new BoxGeometry(0.2, 0.2, 0.2),
    new SphereGeometry(0.12, 12, 8),
    new ConeGeometry(0.12, 0.3, 8),
  ];

  for (let i = 0; i < 3; i++) {
    const mesh = new Mesh(geometries[i]);
    // Random position inside a narrow wedge around the +x axis, so the
    // rotational copies tile the plane without overlapping the origin.
    const angle = rng() * (Math.PI / Math.max(foldsRef.folds, 1));
    const radius = 1.5 + rng() * 1.5;
    const z = (rng() - 0.5) * 0.5;
    mesh.position.set(
      radius * Math.cos(angle),
      radius * Math.sin(angle),
      z
    );
    mesh.rotation.set(rng() * Math.PI, rng() * Math.PI, rng() * Math.PI);
    shard.add(mesh);
  }

  return shard;
}

// Module-level reference set by buildKaleidoscope so buildShard can clamp the
// wedge angle to the wedge size without threading it through every call.
const foldsRef = { folds: 1 };

/**
 * Build a kaleidoscope: one seeded random shard of 3 meshes, replicated
 * `folds` times with rotations of 2*PI*k/folds about the z axis.
 */
export function buildKaleidoscope({ folds, seed }) {
  if (!Number.isInteger(folds) || folds < 1) {
    throw new Error("folds must be a positive integer");
  }
  foldsRef.folds = folds;

  const root = new Group();
  root.name = "kaleidoscope";

  const shard = buildShard(makeRng(seed));
  shard.name = "copy-0";
  root.add(shard);

  for (let k = 1; k < folds; k++) {
    const copy = shard.clone(true);
    copy.name = `copy-${k}`;
    copy.rotation.z = (2 * Math.PI * k) / folds;
    root.add(copy);
  }

  return root;
}

/**
 * World positions of copy k's three meshes, computed after updating world
 * matrices on the whole root.
 */
export function shardWorldPoints(root, k) {
  root.updateMatrixWorld(true);
  const copy = root.getObjectByName(`copy-${k}`);
  if (!copy) throw new Error(`no copy-${k} in root`);
  return copy.children.map((mesh) => mesh.getWorldPosition(new Vector3()));
}

