import { describe, it, expect } from "vitest";
import { Box3, Vector3, MathUtils } from "three";
import { buildKaleidoscope, shardWorldPoints } from "../src/kaleido.js";

function applyInverseRotationZ(points, angle) {
  return points.map((p) => p.clone().applyAxisAngle(new Vector3(0, 0, 1), -angle));
}

function pointsClose(a, b, eps) {
  if (a.length !== b.length) return false;
  return a.every((pa, i) => pa.distanceTo(b[i]) <= eps);
}

describe("buildKaleidoscope", () => {
  const folds = 6;
  const seed = 42;
  const root = buildKaleidoscope({ folds, seed });

  it("has exactly `folds` children under the root", () => {
    expect(root.children.length).toBe(folds);
  });

  it("total mesh count is folds * 3", () => {
    let meshCount = 0;
    root.traverse((obj) => {
      if (obj.isMesh) meshCount++;
    });
    expect(meshCount).toBe(folds * 3);
  });

  it(`with folds = ${folds} the whole root's Box3 center xy is near the origin`, () => {
    root.updateMatrixWorld(true);
    const box = new Box3().setFromObject(root);
    const center = box.getCenter(new Vector3());
    expect(Math.abs(center.x)).toBeLessThan(0.5);
    expect(Math.abs(center.y)).toBeLessThan(0.5);
  });

  it("every copy k, inverse-rotated by 2*PI*k/folds, matches copy 0 within 1e-9", () => {
    const basePoints = shardWorldPoints(root, 0);
    for (let k = 1; k < folds; k++) {
      const points = shardWorldPoints(root, k);
      const rotated = applyInverseRotationZ(points, (2 * Math.PI * k) / folds);
      expect(pointsClose(rotated, basePoints, 1e-9)).toBe(true);
    }
  });

  it("same seed reproduces identical shards", () => {
    const a = buildKaleidoscope({ folds: 8, seed });
    const b = buildKaleidoscope({ folds: 8, seed });
    for (let k = 0; k < 8; k++) {
      const pa = shardWorldPoints(a, k);
      const pb = shardWorldPoints(b, k);
      expect(pa.map((p) => [p.x, p.y, p.z])).toEqual(
        pb.map((p) => [p.x, p.y, p.z])
      );
    }
    // Different seed should differ
    const c = buildKaleidoscope({ folds: 8, seed: seed + 1 });
    const pc = shardWorldPoints(c, 0);
    expect(pointsClose(shardWorldPoints(a, 0), pc, 1e-6)).toBe(false);
  });
});

